findings.codeql_raw_query:
/**
 * @name Tainted eval/exec usage
 * @description Using eval or exec with untrusted input can lead to arbitrary code execution
 * @kind path-problem
 * @problem.severity error
 * @id py/code-injection-tainted
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module TaintedEvalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("builtins").getMember(["eval", "exec", "compile"]).getACall()
      and sink = call.getArg(0)
    )
  }
}

module TaintedEvalFlow = TaintTracking::Global<TaintedEvalConfig>;
import TaintedEvalFlow::PathGraph

from TaintedEvalFlow::PathNode source, TaintedEvalFlow::PathNode sink
where TaintedEvalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Tainted code execution from $@.", source.getNode(), "user input"
